import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../contexts/AuthContext';
import { healthService } from '../services/healthService';
import { userService } from '../services/userService';

const HealthForm = () => {
  const { t } = useTranslation();
  const { patientId } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [patients, setPatients] = useState([]);
  const [selectedPatient, setSelectedPatient] = useState(patientId || '');
  const [formData, setFormData] = useState({
    userId: patientId || '',
    vitalSigns: {
      bloodPressure: { systolic: '', diastolic: '' },
      bloodSugar: { fasting: '', postMeal: '', random: '' },
      heartRate: '',
      temperature: '',
      oxygenSaturation: ''
    },
    physicalMeasurements: {
      height: '',
      weight: ''
    },
    examinations: {
      eyeVision: { leftEye: '', rightEye: '', notes: '' },
      earCheck: { leftEar: '', rightEar: '', notes: '' },
      mouthCheck: { teeth: '', gums: '', throat: '', notes: '' },
      generalExamination: { skin: '', lymphNodes: '', abdomen: '', chest: '', notes: '' }
    },
    symptoms: [],
    diagnosis: {
      primary: '',
      secondary: []
    },
    medications: [],
    recommendations: {
      lifestyle: [],
      followUp: { required: false, date: '', reason: '' },
      referral: { required: false, specialist: '', reason: '', urgency: 'low' }
    },
    doctorRemarks: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    if (!patientId) {
      fetchPatients();
    }
  }, [patientId]);

  const fetchPatients = async () => {
    try {
      const data = await userService.getUsers({ role: 'patient', limit: 100 });
      setPatients(data.users || []);
    } catch (error) {
      console.error('Failed to fetch patients:', error);
    }
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    
    if (name.includes('.')) {
      const keys = name.split('.');
      setFormData(prev => {
        const newData = { ...prev };
        let current = newData;
        
        for (let i = 0; i < keys.length - 1; i++) {
          current = current[keys[i]];
        }
        
        if (type === 'checkbox') {
          current[keys[keys.length - 1]] = checked;
        } else {
          current[keys[keys.length - 1]] = value;
        }
        
        return newData;
      });
    } else {
      setFormData(prev => ({
        ...prev,
        [name]: type === 'checkbox' ? checked : value
      }));
    }
  };

  const addMedication = () => {
    setFormData(prev => ({
      ...prev,
      medications: [...prev.medications, {
        name: '',
        dosage: '',
        frequency: '',
        duration: '',
        instructions: ''
      }]
    }));
  };

  const removeMedication = (index) => {
    setFormData(prev => ({
      ...prev,
      medications: prev.medications.filter((_, i) => i !== index)
    }));
  };

  const updateMedication = (index, field, value) => {
    setFormData(prev => ({
      ...prev,
      medications: prev.medications.map((med, i) => 
        i === index ? { ...med, [field]: value } : med
      )
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (!formData.userId) {
      setError('Please select a patient');
      setLoading(false);
      return;
    }

    try {
      const result = await healthService.createHealthRecord({
        ...formData,
        userId: formData.userId
      });
      
      setSuccess('Health record saved successfully!');
      setTimeout(() => {
        navigate('/dashboard');
      }, 2000);
    } catch (error) {
      setError(error.response?.data?.message || 'Failed to save health record');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container health-form fade-in">
      <div className="card-header text-center">
        <h1 className="card-title">{t('health.healthForm')}</h1>
      </div>

      {error && <div className="alert alert-error">{error}</div>}
      {success && <div className="alert alert-success">{success}</div>}

      <form onSubmit={handleSubmit}>
        {/* Patient Selection */}
        {!patientId && (
          <div className="form-section">
            <h3 className="form-section-title">{t('health.patientInfo')}</h3>
            <div className="form-group">
              <label className="form-label">Select Patient *</label>
              <select
                name="userId"
                className="form-select"
                value={formData.userId}
                onChange={handleChange}
                required
              >
                <option value="">Choose a patient...</option>
                {patients.map(patient => (
                  <option key={patient._id} value={patient._id}>
                    {patient.name} - {patient.phone}
                  </option>
                ))}
              </select>
            </div>
          </div>
        )}

        {/* Vital Signs */}
        <div className="form-section">
          <h3 className="form-section-title">{t('health.vitalSigns')}</h3>
          
          <div className="form-row">
            <div className="form-group">
              <label className="form-label">Blood Pressure (Systolic)</label>
              <input
                type="number"
                name="vitalSigns.bloodPressure.systolic"
                className="form-input"
                value={formData.vitalSigns.bloodPressure.systolic}
                onChange={handleChange}
                placeholder="120"
              />
            </div>
            <div className="form-group">
              <label className="form-label">Blood Pressure (Diastolic)</label>
              <input
                type="number"
                name="vitalSigns.bloodPressure.diastolic"
                className="form-input"
                value={formData.vitalSigns.bloodPressure.diastolic}
                onChange={handleChange}
                placeholder="80"
              />
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="form-label">Blood Sugar (Fasting)</label>
              <input
                type="number"
                name="vitalSigns.bloodSugar.fasting"
                className="form-input"
                value={formData.vitalSigns.bloodSugar.fasting}
                onChange={handleChange}
                placeholder="100"
              />
            </div>
            <div className="form-group">
              <label className="form-label">Blood Sugar (Post Meal)</label>
              <input
                type="number"
                name="vitalSigns.bloodSugar.postMeal"
                className="form-input"
                value={formData.vitalSigns.bloodSugar.postMeal}
                onChange={handleChange}
                placeholder="140"
              />
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label className="form-label">Heart Rate (bpm)</label>
              <input
                type="number"
                name="vitalSigns.heartRate"
                className="form-input"
                value={formData.vitalSigns.heartRate}
                onChange={handleChange}
                placeholder="72"
              />
            </div>
            <div className="form-group">
              <label className="form-label">Temperature (°F)</label>
              <input
                type="number"
                step="0.1"
                name="vitalSigns.temperature"
                className="form-input"
                value={formData.vitalSigns.temperature}
                onChange={handleChange}
                placeholder="98.6"
              />
            </div>
          </div>
        </div>

        {/* Physical Measurements */}
        <div className="form-section">
          <h3 className="form-section-title">{t('health.physicalMeasurements')}</h3>
          
          <div className="form-row">
            <div className="form-group">
              <label className="form-label">Height (cm)</label>
              <input
                type="number"
                name="physicalMeasurements.height"
                className="form-input"
                value={formData.physicalMeasurements.height}
                onChange={handleChange}
                placeholder="170"
              />
            </div>
            <div className="form-group">
              <label className="form-label">Weight (kg)</label>
              <input
                type="number"
                step="0.1"
                name="physicalMeasurements.weight"
                className="form-input"
                value={formData.physicalMeasurements.weight}
                onChange={handleChange}
                placeholder="70"
              />
            </div>
          </div>
        </div>

        {/* Diagnosis */}
        <div className="form-section">
          <h3 className="form-section-title">{t('health.diagnosis')}</h3>
          
          <div className="form-group">
            <label className="form-label">Primary Diagnosis</label>
            <input
              type="text"
              name="diagnosis.primary"
              className="form-input"
              value={formData.diagnosis.primary}
              onChange={handleChange}
              placeholder="Enter primary diagnosis"
            />
          </div>
        </div>

        {/* Medications */}
        <div className="form-section">
          <h3 className="form-section-title">{t('health.medications')}</h3>
          
          {formData.medications.map((medication, index) => (
            <div key={index} className="card" style={{ marginBottom: '1rem' }}>
              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Medicine Name</label>
                  <input
                    type="text"
                    className="form-input"
                    value={medication.name}
                    onChange={(e) => updateMedication(index, 'name', e.target.value)}
                    placeholder="Medicine name"
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">Dosage</label>
                  <input
                    type="text"
                    className="form-input"
                    value={medication.dosage}
                    onChange={(e) => updateMedication(index, 'dosage', e.target.value)}
                    placeholder="5mg"
                  />
                </div>
              </div>
              
              <div className="form-row">
                <div className="form-group">
                  <label className="form-label">Frequency</label>
                  <select
                    className="form-select"
                    value={medication.frequency}
                    onChange={(e) => updateMedication(index, 'frequency', e.target.value)}
                  >
                    <option value="">Select frequency</option>
                    <option value="once daily">Once daily</option>
                    <option value="twice daily">Twice daily</option>
                    <option value="thrice daily">Thrice daily</option>
                    <option value="four times daily">Four times daily</option>
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Duration</label>
                  <input
                    type="text"
                    className="form-input"
                    value={medication.duration}
                    onChange={(e) => updateMedication(index, 'duration', e.target.value)}
                    placeholder="7 days"
                  />
                </div>
              </div>
              
              <div className="form-group">
                <label className="form-label">Instructions</label>
                <input
                  type="text"
                  className="form-input"
                  value={medication.instructions}
                  onChange={(e) => updateMedication(index, 'instructions', e.target.value)}
                  placeholder="Take with food"
                />
              </div>
              
              <button
                type="button"
                className="btn btn-danger"
                onClick={() => removeMedication(index)}
              >
                Remove Medicine
              </button>
            </div>
          ))}
          
          <button
            type="button"
            className="btn btn-secondary"
            onClick={addMedication}
          >
            Add Medicine
          </button>
        </div>

        {/* Doctor's Remarks */}
        <div className="form-section">
          <h3 className="form-section-title">{t('health.doctorRemarks')}</h3>
          
          <div className="form-group">
            <label className="form-label">Remarks</label>
            <textarea
              name="doctorRemarks"
              className="form-textarea"
              value={formData.doctorRemarks}
              onChange={handleChange}
              placeholder="Enter your observations and recommendations..."
              rows="4"
            />
          </div>
        </div>

        <button
          type="submit"
          className="btn"
          disabled={loading}
          style={{ width: '100%' }}
        >
          {loading ? 'Saving...' : t('health.saveRecord')}
        </button>
      </form>
    </div>
  );
};

export default HealthForm;
